function fresh(){return {appointments:[],requests:[],programs:[],tasks:[],stock:[],teamRequests:[],sessions:[],facilities:[],governance:[],profile:{centerName:'مراكز الإرتقاء الفكري الصحية',intro:'منظومة تنظيمية مستقلة لتنسيق الخدمات الصحية والإدارية ومتابعة الخطط والمهام.',contact:'يُضاف بعد اعتماد بيانات التواصل',location:'يُحدد عند اعتماد الفرع',services:'تنسيق المواعيد\\nالاستفسارات والطلبات الإدارية\\nالبرامج التوعوية العامة\\nالمهام والمناوبات\\nالمخزون والصيانة العامة',contentStatus:'مسودة تحتاج مراجعة واعتماد'}};}
function load(){try{var raw=localStorage.getItem(STORE_KEY);if(!raw)return fresh();var data=JSON.parse(raw);var d=fresh();['appointments','requests','programs','tasks','stock','teamRequests','sessions','facilities','governance'].forEach(function(k){if(Array.isArray(data[k]))d[k]=data[k];});if(data.profile&&typeof data.profile==='object')Object.keys(d.profile).forEach(function(k){if(typeof data.profile[k]==='string')d.profile[k]=data.profile[k];});return d;}catch(e){return fresh();}}
