function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(db));return true;}catch(e){notify('تعذر الحفظ محليًا. تحقق من مساحة المتصفح وإعداداته.');return false;}}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function fmtDate(v){if(!v)return 'غير محدد';var d=new Date(v+'T00:00:00');if(isNaN(d.getTime()))return esc(v);return new Intl.DateTimeFormat('ar',{year:'numeric',month:'short',day:'numeric'}).format(d);}
function notify(msg){var t=document.getElementById('toast');if(!t)return;t.textContent=msg;t.classList.add('show');window.clearTimeout(t._hideTimer);t._hideTimer=window.setTimeout(function(){t.classList.remove('show');},3500);}
function countOpen(list){return db[list].filter(function(x){return x.status!=='مكتمل'&&x.status!=='ملغي';}).length;}
function wrapIntro(title,desc,kicker){return '<section class="page-intro"><div><div class="eyebrow">'+esc(kicker||'مراكز الإرتقاء الفكري الصحية')+'</div><h1>'+esc(title)+'</h1><p>'+esc(desc)+'</p></div></section>';}
function stat(label,value,help,icon){return '<article class="stat-card"><div class="stat-label">'+esc(icon||'•')+' '+esc(label)+'</div><div class="stat-value">'+esc(value)+'</div><div class="stat-help">'+esc(help)+'</div></article>';}
function empty(text){return '<div class="empty">'+esc(text)+'</div>';}
function formField(name,label,type,required,placeholder,extra){return '<div class="field"><label for="f-'+esc(name)+'">'+esc(label)+(required?' <span aria-hidden="true">*</span>':'')+'</label><input id="f-'+esc(name)+'" name="'+esc(name)+'" type="'+esc(type||'text')+'" '+(required?'required ':'')+(placeholder?'placeholder="'+esc(placeholder)+'" ':'')+(extra||'')+'></div>';}
function selectField(name,label,items,required){return '<div class="field"><label for="f-'+esc(name)+'">'+esc(label)+(required?' <span aria-hidden="true">*</span>':'')+'</label><select id="f-'+esc(name)+'" name="'+esc(name)+'" '+(required?'required':'')+'><option value="">اختر…</option>'+items.map(function(x){return '<option value="'+esc(x[0])+'">'+esc(x[1])+'</option>';}).join('')+'</select></div>';}
function textField(name,label,required,placeholder){return '<div class="field full"><label for="f-'+esc(name)+'">'+esc(label)+(required?' <span aria-hidden="true">*</span>':'')+'</label><textarea id="f-'+esc(name)+'" name="'+esc(name)+'" '+(required?'required ':'')+'placeholder="'+esc(placeholder||'')+'"></textarea></div>';}
function recordTools(list,item){var label=item.status==='مكتمل'?'إعادة فتح':'تحديث الحالة';return '<div class="record-tools"><span class="pill '+(item.status==='مكتمل'?'':'gold')+'">'+esc(item.status||'جديد')+'</span><button class="btn btn-light btn-small" data-action="toggle" data-list="'+esc(list)+'" data-id="'+esc(item.id)+'">'+label+'</button></div>';}
function listRecords(list,rows,none){if(!rows.length)return empty(none);return '<div class="record-list">'+rows.map(function(item){return '<article class="record"><div class="record-main"><div class="record-title">'+esc(item.title||item.name||item.item||'عنصر')+'</div><div class="record-meta">'+esc(item.meta||'')+'</div>'+(item.notes?'<div class="record-notes">'+esc(item.notes)+'</div>':'')+'</div>'+recordTools(list,item)+'</article>';}).join('')+'</div>';}
