function safeZoomUrl(value){
 try{var u=new URL(String(value||''));return u.protocol==='https:'&&(u.hostname==='zoom.us'||u.hostname.endsWith('.zoom.us')||u.hostname==='zoom.com'||u.hostname.endsWith('.zoom.com'));}catch(e){return false;}
}
