var RENDERERS={home:renderHome,'quick-access':renderQuickAccess,services:renderServices,specialties:renderSpecialties,team:renderTeam,sessions:renderSessions,facilities:renderFacilities,readiness:renderReadiness,appointments:renderAppointments,requests:renderRequests,programs:renderPrograms,tasks:renderTasks,stock:renderStock,reports:renderReports,content:renderContent,settings:renderSettings};
function route(){var id=(location.hash||'#home').slice(1);if(!RENDERERS[id])id='home';document.getElementById('top-title').textContent=TITLES[id]||TITLES.home;document.getElementById('nav').innerHTML=NAV.map(function(n){return '<a class="nav-link '+(n.id===id?'active':'')+'" href="#'+n.id+'" '+(n.id===id?'aria-current="page"':'')+'><span class="nav-icon">'+n.icon+'</span><span>'+esc(n.label)+'</span></a>';}).join('');document.getElementById('view').innerHTML=RENDERERS[id]();if(id==='content'){var cf=document.querySelector('#view form[data-type="profile"]');if(cf){['centerName','contact','location','intro','services'].forEach(function(k){var el=cf.elements.namedItem(k);if(el)el.value=db.profile[k]||'';});var st=cf.elements.namedItem('contentStatus');if(st)st.value=db.profile.contentStatus||'مسودة تحتاج مراجعة واعتماد';}}document.title=(TITLES[id]||TITLES.home)+' | مراكز الإرتقاء الفكري الصحية';bindForms();window.scrollTo({top:0,behavior:'smooth'});}
function bindForms(){document.querySelectorAll('#view form[data-type]').forEach(function(form){form.addEventListener('submit',function(e){e.preventDefault();var type=form.getAttribute('data-type');var obj={};new FormData(form).forEach(function(v,k){obj[k]=String(v);});if(type==='sessions'&&obj.meetingUrl&&!safeZoomUrl(obj.meetingUrl)){notify('أدخل رابط HTTPS رسميًا من نطاق zoom.us أو نطاق تابع له.');return;}if(type==='profile'){db.profile=obj;if(persist()){notify('تم حفظ المسودة على هذا الجهاز فقط.');route();}return;}obj.id=String(Date.now())+'-'+Math.random().toString(36).slice(2,7);obj.createdAt=new Date().toISOString();obj.status=type==='appointments'?'بانتظار التأكيد':(type==='programs'?'مسودة':(type==='sessions'?(obj.meetingUrl?'رابط مدخل — غير مختبر':'بانتظار الربط'):(type==='teamRequests'?'طلب تجهيز — غير معتمد':(type==='facilities'?'بانتظار المطابقة الميدانية':(type==='governance'?'توثيق محلي — غير معتمد':'قيد المتابعة')))));db[type].unshift(obj);if(persist()){notify(type==='appointments'?'تم حفظ الموعد محليًا، ولم يُرسل للمركز.':'تم حفظ السجل على هذا الجهاز.');route();}});});}
function csvCell(v){var s=String(v==null?'':v);return '"'+s.replace(/"/g,'""')+'"';}
function exportFile(which){var payload,name,mime;if(which==='backup'){payload=JSON.stringify({exportedAt:new Date().toISOString(),note:'نسخة محلية؛ لا تتضمن اتصالًا بقاعدة مركزية.',data:db},null,2);name='irtiqaa-health-local-backup.json';mime='application/json;charset=utf-8';}else{var labels={appointments:{name:'الاسم',phone:'التواصل',service:'الخدمة',date:'التاريخ',time:'الوقت',branch:'المركز أو الفرع',status:'الحالة',createdAt:'تاريخ التسجيل'},requests:{title:'الطلب',type:'التصنيف',priority:'الأولوية',dueDate:'الموعد',owner:'المسؤول',status:'الحالة',notes:'ملاحظات إدارية'},tasks:{title:'المهمة',role:'المسؤول',priority:'الأولوية',dueDate:'موعد الإنجاز',status:'الحالة',notes:'التفاصيل'},stock:{item:'البند',category:'الفئة',quantity:'الكمية',minimum:'حد إعادة الطلب',unit:'الوحدة',expiry:'الصلاحية أو المراجعة',status:'الحالة'},teamRequests:{requestedRole:'الدور المطلوب',unit:'الوحدة',priority:'الأولوية',start:'موعد متوقع',status:'الحالة',notes:'ملاحظات'},sessions:{title:'عنوان الجلسة',sessionType:'نوع الجلسة',hostRole:'الدور المنظم',date:'التاريخ',time:'الوقت',meetingUrl:'رابط Zoom',status:'الحالة',notes:'ملاحظات'},facilities:{item:'الأصل أو التجهيز',category:'الفئة',location:'الموقع',quantity:'الكمية',unit:'الوحدة',condition:'الحالة الميدانية',inspectionDate:'تاريخ الجرد',status:'حالة السجل',notes:'ملاحظات'},governance:{gate:'المتطلب',reviewStatus:'حالة المراجعة',evidenceRef:'مرجع الإثبات',reviewDate:'تاريخ المراجعة',notes:'ملاحظات',status:'حالة التوثيق'}};var keys=Object.keys(labels[which]||{});payload='\\uFEFF'+[keys.map(function(k){return csvCell(labels[which][k]);}).join(','),db[which].map(function(r){return keys.map(function(k){return csvCell(r[k]);}).join(',');}).join('\\r\\n')].join('\\r\\n');name='irtiqaa-health-'+which+'.csv';mime='text/csv;charset=utf-8';}var blob=new Blob([payload],{type:mime});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);notify('تم تجهيز ملف التنزيل على الجهاز.');}
document.addEventListener('click',function(e){var t=e.target.closest('[data-action],[data-export],#install-button');if(!t)return;if(t.hasAttribute('data-export')){exportFile(t.getAttribute('data-export'));return;}if(t.id==='install-button'){if(window._installPrompt){window._installPrompt.prompt();window._installPrompt.userChoice.then(function(){window._installPrompt=null;document.getElementById('install-card').classList.remove('show');});}else notify('افتح قائمة المتصفح واختر «إضافة إلى الشاشة الرئيسية» عند توفرها.');return;}var action=t.getAttribute('data-action');if(action==='toggle'){var arr=db[t.getAttribute('data-list')]||[];var rec=arr.find(function(x){return String(x.id)===t.getAttribute('data-id');});if(rec){if(t.getAttribute('data-list')==='appointments'){rec.status=rec.status==='بانتظار التأكيد'?'تم التأكيد':(rec.status==='تم التأكيد'?'مكتمل':'بانتظار التأكيد');}else if(t.getAttribute('data-list')==='programs'){rec.status=rec.status==='معتمد'?'مسودة':(rec.status==='مكتمل'?'مسودة':'مكتمل');}else{rec.status=rec.status==='مكتمل'?'قيد المتابعة':'مكتمل';}persist();route();notify('تم تحديث الحالة محليًا.');}return;}if(action==='template'){db.programs.unshift({id:String(Date.now()),title:t.getAttribute('data-title'),category:t.getAttribute('data-category'),start:'',end:'',owner:'',goal:'يحدد عند إعداد الخطة',notes:'مسودة مقترحة تحتاج مراجعة واعتماد المسؤول المختص.',status:'مسودة',createdAt:new Date().toISOString()});if(persist()){route();notify('أنشئت مسودة البرنامج على هذا الجهاز.');}}});
window.addEventListener('beforeinstallprompt',function(e){e.preventDefault();window._installPrompt=e;});
